<div class="form-section"><div class="form-section__heading form-heading-row"><div><span class="eyebrow">Items</span><h3>Products being purchased</h3></div><button class="button button--secondary" type="button" data-add-purchase-row>+ Add row</button></div><div class="table-wrap"><table class="data-table purchase-builder-table"><thead><tr><th>Product</th><th>Quantity</th><th>Unit cost</th><th>Line total</th><th></th></tr></thead><tbody data-purchase-rows></tbody></table></div></div>
<div class="form-section"><div class="form-grid"><div class="field"><label>Purchase discount</label><input type="number" name="discount_amount" min="0" step="0.01" value="0.00"></div><div class="field"><label>Amount paid now</label><input type="number" name="amount_paid" min="0" step="0.01" value="0.00"></div><div class="field"><label>Payment method</label><select name="payment_method_id"><option value="0">Select if paying now</option><?php foreach($paymentMethods as$m):?><option value="<?=e((string)$m['id'])?>"><?=e($m['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Payment reference</label><input name="payment_reference" maxlength="120" placeholder="M-Pesa / bank / card reference"></div><div class="field field--span-2"><label>Notes</label><textarea name="notes" rows="3"></textarea></div></div><div class="purchase-summary"><span>Purchase total</span><strong><?=e(APP_CURRENCY_SYMBOL)?> <span data-purchase-total>0.00</span></strong></div></div>
